SELECT ui.*, ei.event_name FROM user_interaction ui
LEFT JOIN event_info ei ON ui.event_id = ei.event_id
ORDER BY ui.created_at DESC LIMIT #{limit}

SELECT us.*, ei.event_name FROM user_submission us
LEFT JOIN event_info ei ON us.event_id = ei.event_id
ORDER BY us.created_at DESC LIMIT #{limit}
